/**
 * Consensus Judge - Multi-Sample Tier 3 Verification
 *
 * Runs the same judge evaluation multiple times and takes the median
 * to reduce non-determinism. Optionally uses cross-model judging
 * (different model judges different model's output) to reduce substrate bias.
 *
 * Key design:
 * - Multiple samples at temperature 0 -> take median (robust to outliers)
 * - Flag disagreements (if range > 1 across samples = low confidence)
 * - Cross-model judging: output generated by model A, judged by model B
 * - Adversarial framing: "find weaknesses FIRST, then score"
 *
 * This file is the **public barrel** for consensus judging. The supporting
 * seams live alongside it and are re-exported here so the public surface
 * stays a single `./consensus.js` import path:
 * - ./consensus-types.js    - the type vocabulary (consensus options/result,
 *                             criterion agreement, adversarial/cross-model options)
 * - ./consensus-analysis.js - the engine (runConsensus, AdversarialJudge,
 *                             CrossModelJudge + the assertion factories)
 *
 * @tier 3 - Enhanced Judgment (more reliable than single-shot judge)
 * @module
 */

// --- TYPE RE-EXPORTS -----------------------------------------------------------
// The consensus type vocabulary lives in ./consensus-types.js; re-export it
// here so consumers keep a single `./consensus.js` import path.
export type {
  ConsensusOptions,
  ConsensusResult,
  CriterionAgreement,
  AdversarialOptions,
  CrossModelOptions,
} from './consensus-types.js';

// --- ENGINE RE-EXPORTS ---------------------------------------------------------
// The consensus engine, adversarial/cross-model judges, and assertion factories
// live in ./consensus-analysis.js; re-export them through this barrel.
export {
  runConsensus,
  AdversarialJudge,
  CrossModelJudge,
  toPassConsensusJudge,
  toPassAdversarialJudge,
} from './consensus-analysis.js';